import json
def solve(g):
    h=len(g); w=len(g[0]); out=[row[:] for row in g]
    seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=8 and not seen[r][c]:
                stack=[(r,c)]; seen[r][c]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]!=8 and not seen[ny][nx]:
                            seen[ny][nx]=True; stack.append((ny,nx))
                rt=min(p[0] for p in cells); rb=max(p[0] for p in cells)
                cl=min(p[1] for p in cells); cr=max(p[1] for p in cells)
                col=[p for p in cells if g[p[0]][p[1]]!=0]
                r0=min(p[0] for p in col); r1=max(p[0] for p in col)
                c0=min(p[1] for p in col); c1=max(p[1] for p in col)
                th,tw=r1-r0+1,c1-c0+1
                pat=[[g[r0+i][c0+j] for j in range(tw)] for i in range(th)]
                for r in range(rt,rb+1):
                    for c in range(cl,cr+1):
                        out[r][c]=pat[(r-r0)%th][(c-c0)%tw]
    return out
